import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { createClient, type Session, type SupabaseClient } from '@supabase/supabase-js';
import {
  Home, CalendarDays, CheckSquare, FileText, BookOpen, Users, Settings, ShieldCheck, Upload, Download,
  Plus, Search, Menu, X, LayoutDashboard, GraduationCap, Clock3, ClipboardList, PartyPopper, Brush,
  Newspaper, MessageCircle, Timer, Wallet, ScanLine, Images, BarChart3, SlidersHorizontal, Megaphone,
  LogOut, Trash2, Edit3, Save, ChevronRight, Database, CircleCheck, CircleAlert, Languages, Bell,
  MoreHorizontal, LockKeyhole, UserRound, ArrowRight, Sparkles, FolderOpen, Shield, Eye, EyeOff, Pin,
  Send, ThumbsUp, UserPlus, Copy, Check, RotateCcw, ImagePlus, Link2, CalendarPlus, AlertTriangle,
  GraduationCap as Grad, Menu as MenuIcon, FilePlus2, UserCog, Palette, MessageSquare, Hash, DoorOpen,
  Banknote, QrCode, Activity, Wrench, HelpCircle
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import './styles.css';

type Page = 'Home'|'Schedule'|'Tasks'|'Exams'|'Calendar'|'Class Files'|'Events'|'Duty'|'Weekly'|'Community'|'Study Rooms'|'Gallery'|'Class Fund'|'Attendance'|'Members'|'Class Pulse'|'Admin Center'|'Class Setup'|'Subjects'|'Announcements'|'Activity Logs'|'Feature Control'|'Settings';
type Lang = 'th'|'en';
type Role = 'owner'|'admin'|'teacher'|'treasurer'|'reporter'|'duty_manager'|'moderator'|'student';
type Row = { id?:string; [key:string]: any };
type FeatureFlags = Record<Page, boolean>;

type User = { id:string; name:string; email:string; roles:Role[]; avatar?:string };
type Store = {
  classroomId:string;
  classroom:{name:string;program:string;year:string;code:string;description:string;theme:string;humor:string;coverUrl:string;logoUrl:string;accent:string};
  members:Row[]; subjects:Row[]; schedules:Row[]; tasks:Row[]; exams:Row[]; events:Row[]; announcements:Row[];
  duties:Row[]; weekly:Row[]; channels:Row[]; messages:Row[]; rooms:Row[]; transactions:Row[]; attendance:Row[];
  files:Row[]; gallery:Row[]; activity:Row[]; polls:Row[]; features:FeatureFlags;
};

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string|undefined;
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY as string|undefined;
const supabase: SupabaseClient|null = supabaseUrl && supabaseAnonKey ? createClient(supabaseUrl,supabaseAnonKey) : null;
const uid=()=>crypto.randomUUID();
const isoNow=()=>new Date().toISOString();
const emptyStore=():Store=>({
 classroomId:'',
 classroom:{name:'',program:'',year:'',code:'',description:'',theme:'sage',humor:'off',coverUrl:'',logoUrl:'',accent:'sage'},
 members:[],subjects:[],schedules:[],tasks:[],exams:[],events:[],announcements:[],duties:[],weekly:[],channels:[],messages:[],rooms:[],transactions:[],attendance:[],files:[],gallery:[],activity:[],polls:[],
 features:{Home:true,Schedule:true,Tasks:true,Exams:true,Calendar:true,'Class Files':true,Events:true,Duty:true,Weekly:true,Community:true,'Study Rooms':true,Gallery:true,'Class Fund':false,Attendance:false,Members:true,'Class Pulse':true,'Admin Center':true,'Class Setup':true,Subjects:true,Announcements:true,'Activity Logs':true,'Feature Control':true,Settings:true}
});
const loadStore=():Store=>{try{const raw=localStorage.getItem('classroom-os-v2');return raw?{...emptyStore(),...JSON.parse(raw)}:emptyStore()}catch{return emptyStore()}};
const saveStore=(s:Store)=>localStorage.setItem('classroom-os-v2',JSON.stringify(s));
const loadUser=():User|null=>{try{const r=localStorage.getItem('classroom-os-user');return r?JSON.parse(r):null}catch{return null}};

const navGroups:{name:string;items:{p:Page;icon:LucideIcon}[]}[]=[
 {name:'MAIN',items:[{p:'Home',icon:Home},{p:'Admin Center',icon:LayoutDashboard}]},
 {name:'ACADEMIC',items:[{p:'Schedule',icon:CalendarDays},{p:'Tasks',icon:CheckSquare},{p:'Exams',icon:FileText},{p:'Calendar',icon:CalendarDays},{p:'Subjects',icon:GraduationCap}]},
 {name:'CLASS',items:[{p:'Class Files',icon:FolderOpen},{p:'Events',icon:PartyPopper},{p:'Duty',icon:Brush},{p:'Weekly',icon:Newspaper},{p:'Announcements',icon:Megaphone},{p:'Gallery',icon:Images}]},
 {name:'COMMUNITY',items:[{p:'Community',icon:MessageCircle},{p:'Study Rooms',icon:Timer}]},
 {name:'MANAGEMENT',items:[{p:'Members',icon:Users},{p:'Attendance',icon:ScanLine},{p:'Class Fund',icon:Wallet},{p:'Class Pulse',icon:BarChart3}]}
];
const adminItems:{p:Page;icon:LucideIcon}[]=[{p:'Class Setup',icon:Wrench},{p:'Activity Logs',icon:Database},{p:'Feature Control',icon:SlidersHorizontal},{p:'Settings',icon:Settings}];
const th:Record<Page,string>={Home:'หน้าหลัก','Admin Center':'ศูนย์ควบคุม',Schedule:'ตารางเรียน',Tasks:'งาน',Exams:'ข้อสอบ / สอบ',Calendar:'ปฏิทิน','Class Files':'ไฟล์ของห้อง',Events:'กิจกรรม',Duty:'เวร',Weekly:'เดอะวีคลี่',Community:'ชุมชน','Study Rooms':'ห้องอ่านหนังสือ',Gallery:'Class Moments','Class Fund':'กองกลาง',Attendance:'เช็กชื่อ',Members:'สมาชิกและสิทธิ์','Class Pulse':'Class Pulse','Class Setup':'ตั้งค่าห้อง',Subjects:'วิชา',Announcements:'ประกาศ','Activity Logs':'ประวัติการทำงาน','Feature Control':'เปิด/ปิดฟีเจอร์',Settings:'ตั้งค่าระบบ'};
const roleLabel:Record<Role,string>={owner:'Owner',admin:'Admin',teacher:'Teacher',treasurer:'Treasurer',reporter:'Reporter',duty_manager:'Duty Manager',moderator:'Moderator',student:'Student'};
const en:Record<Page,string>=Object.fromEntries(Object.keys(th).map(k=>[k,k])) as Record<Page,string>;
const pageLabel=(p:Page,l:Lang)=>l==='th'?th[p]:en[p];
const can=(u:User|null,roles:Role[])=>!!u&&roles.some(r=>u.roles.includes(r));
const formatDate=(d:any)=>d?new Date(d).toLocaleDateString('th-TH',{day:'2-digit',month:'short',year:'numeric'}):'—';
const formatDateTime=(d:any)=>d?new Date(d).toLocaleString('th-TH',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const formatSize=(n:number)=>{if(!n)return'0 KB';const u=['B','KB','MB','GB'];let i=0,x=n;while(x>=1024&&i<3){x/=1024;i++}return`${x.toFixed(i?1:0)} ${u[i]}`};

async function getCloudContext(userId:string){
 if(!supabase)return null;
 try{
  const a=await supabase.from('classroom_os_members').select('classroom_id,display_name,roles').eq('user_id',userId).eq('active',true).limit(1).maybeSingle();
  if(a.data)return {classroomId:a.data.classroom_id,name:a.data.display_name as string|undefined,roles:(a.data.roles||['student']) as Role[]};
  const b=await supabase.from('classroom_members').select('classroom_id,display_name,roles').eq('user_id',userId).eq('is_active',true).limit(1).maybeSingle();
  if(b.data)return {classroomId:b.data.classroom_id,name:b.data.display_name as string|undefined,roles:(b.data.roles||['student']) as Role[]};
 }catch{}
 return null;
}
async function loadCloudState(classroomId:string):Promise<Partial<Store>|null>{
 if(!supabase||!classroomId)return null;
 try{const r=await supabase.from('classroom_os_state').select('state').eq('classroom_id',classroomId).maybeSingle();return r.data?.state||null}catch{return null}
}
async function saveCloudState(classroomId:string,state:Store){
 if(!supabase||!classroomId)return;
 try{await supabase.from('classroom_os_state').upsert({classroom_id:classroomId,state,updated_at:new Date().toISOString()},{onConflict:'classroom_id'})}catch{}
}

function App(){
 const [store,setStore]=useState<Store>(loadStore); const [user,setUser]=useState<User|null>(loadUser); const [session,setSession]=useState<Session|null>(null); const [cloudReady,setCloudReady]=useState(!supabase);
 const [page,setPage]=useState<Page>('Home'); const [lang,setLang]=useState<Lang>('th'); const [mobileOpen,setMobileOpen]=useState(false); const [query,setQuery]=useState(''); const [toast,setToast]=useState(''); const [authLoading,setAuthLoading]=useState(!!supabase);
 useEffect(()=>saveStore(store),[store]);
 useEffect(()=>{if(!supabase){setAuthLoading(false);return} let alive=true; const hydrate=async(s:Session|null)=>{setSession(s); if(!s){if(alive)setUser(null);return} const au=s.user; let roles:Role[]=['student']; let name=(au.user_metadata?.display_name as string)||au.email?.split('@')[0]||'Student'; try { const q1=await supabase!.from('classroom_members').select('roles,display_name').eq('user_id',au.id).eq('is_active',true).limit(1).maybeSingle(); const q2=!q1.data ? await supabase!.from('classroom_os_members').select('roles,display_name').eq('user_id',au.id).eq('active',true).limit(1).maybeSingle() : null; const row=q1.data||q2?.data; if(row?.roles?.length) roles=row.roles as Role[]; if(row?.display_name) name=row.display_name; } catch {} if(alive){const u={id:au.id,name,email:au.email||'',roles};setUser(u);localStorage.setItem('classroom-os-user',JSON.stringify(u));}}; supabase.auth.getSession().then(({data})=>{if(alive)void hydrate(data.session);else setAuthLoading(false)}); const {data}=supabase.auth.onAuthStateChange((_e,s)=>{void hydrate(s)}); setAuthLoading(false); return()=>{alive=false;data.subscription.unsubscribe()}},[]);
 useEffect(()=>{if(!supabase||!user)return;let alive=true;(async()=>{const ctx=await getCloudContext(user.id);if(!alive)return;if(ctx){setStore(prev=>({...prev,classroomId:ctx.classroomId}));const remote=await loadCloudState(ctx.classroomId);if(alive&&remote)setStore(prev=>({...prev,...remote,classroomId:ctx.classroomId}));}setCloudReady(true)})().catch(()=>setCloudReady(true));return()=>{alive=false}},[user?.id]);
useEffect(()=>{if(!supabase||!cloudReady||!store.classroomId||!user)return;const t=setTimeout(()=>{void saveCloudState(store.classroomId,store)},650);return()=>clearTimeout(t)},[store,cloudReady,user?.id]);
useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),2500);return()=>clearTimeout(t)}},[toast]);
 const update=(fn:(s:Store)=>void)=>setStore(prev=>{const n=structuredClone(prev);fn(n);return n});
 const log=(action:string,entity:string,meta:any={})=>update(s=>s.activity.unshift({id:uid(),action,entity,meta,created_at:isoNow(),user:user?.name||'Local User'}));
 const notify=(x:string)=>setToast(x);
 const isAdmin=can(user,['owner','admin']);
 if(authLoading)return <div className="splash"><div className="brandMark large">C</div><h1>CLASSROOM OS</h1><p>กำลังเชื่อมต่อระบบ…</p></div>;
 if(!user)return <AuthScreen onLogin={(u)=>{setUser(u);localStorage.setItem('classroom-os-user',JSON.stringify(u));}} store={store} update={update}/>;
 const visibleGroups=navGroups.map(g=>({...g,items:g.items.filter(x=>store.features[x.p]!==false && (x.p!=='Admin Center'||isAdmin))})).filter(g=>g.items.length);
 const go=(p:Page)=>{setPage(p);setMobileOpen(false);setQuery('')};
 const content=<>
  {page==='Home'&&<HomePage store={store} user={user} go={go} lang={lang} />}
  {page==='Admin Center'&&isAdmin&&<AdminCenter store={store} user={user} go={go} lang={lang}/>} 
  {page==='Class Setup'&&isAdmin&&<ClassSetup store={store} update={update} log={log} notify={notify}/>} 
  {page==='Subjects'&&<SubjectsPage store={store} update={update} log={log} notify={notify}/>} 
  {page==='Schedule'&&<SchedulePage store={store} update={update} log={log} notify={notify}/>} 
  {page==='Tasks'&&<TasksPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Exams'&&<ExamsPage store={store} update={update} log={log} notify={notify}/>} 
  {page==='Calendar'&&<CalendarPage store={store}/>} 
  {page==='Events'&&<EventsPage store={store} update={update} log={log} notify={notify}/>} 
  {page==='Announcements'&&<AnnouncementsPage store={store} update={update} log={log} notify={notify}/>} 
  {page==='Duty'&&<DutyPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Weekly'&&<WeeklyPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Community'&&<CommunityPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Study Rooms'&&<StudyPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Class Files'&&<FilesPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Gallery'&&<GalleryPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Class Fund'&&<FundPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Attendance'&&<AttendancePage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Members'&&<MembersPage store={store} update={update} user={user} log={log} notify={notify}/>} 
  {page==='Class Pulse'&&<PulsePage store={store}/>} 
  {page==='Activity Logs'&&isAdmin&&<LogsPage store={store}/>} 
  {page==='Feature Control'&&isAdmin&&<FeaturesPage store={store} update={update}/>} 
  {page==='Settings'&&isAdmin&&<SettingsPage store={store} update={update} log={log} notify={notify}/>} 
 </>;
 return <div className={`app theme-${store.classroom.theme}`}>
  <aside className={`sidebar ${mobileOpen?'open':''}`}>
   <div className="brand"><div className="brandMark">C</div><div><b>CLASSROOM OS</b><span>class operating system</span></div><button className="mobileClose" onClick={()=>setMobileOpen(false)}><X size={18}/></button></div>
   <div className="classMini"><div className="classAvatar">{store.classroom.logoUrl?<img src={store.classroom.logoUrl}/>:<Grad size={19}/>}</div><div><strong>{store.classroom.name||'YOUR CLASS'}</strong><small>{store.classroom.program||'ตั้งค่าห้องเพื่อเริ่มต้น'}</small></div></div>
   <nav>{visibleGroups.map(g=><div className="navGroup" key={g.name}><small>{g.name}</small>{g.items.map(n=><NavButton key={n.p} n={n} active={page===n.p} onClick={()=>go(n.p)} />)}</div>)}
    {isAdmin&&<div className="navGroup"><small>ADMIN</small>{adminItems.filter(n=>store.features[n.p]!==false).map(n=><NavButton key={n.p} n={n} active={page===n.p} onClick={()=>go(n.p)}/>)}</div>}
   </nav>
   <div className="sidebarBottom"><div className="miniUser"><div className="avatar">{user.name.slice(0,1)}</div><div><b>{user.name}</b><span>{roleLabel[user.roles[0]]}</span></div></div><button className="logout" onClick={async()=>{if(supabase)await supabase.auth.signOut();localStorage.removeItem('classroom-os-user');setUser(null)}}><LogOut size={16}/></button></div>
  </aside>
  {mobileOpen&&<div className="backdrop" onClick={()=>setMobileOpen(false)}/>} 
  <main className="main">
   <header><button className="mobileMenu" onClick={()=>setMobileOpen(true)}><MenuIcon/></button><div className="crumb"><span>CLASSROOM OS</span><ChevronRight size={14}/><b>{pageLabel(page,lang)}</b></div><div className="topActions"><div className="search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={lang==='th'?'ค้นหาในห้อง…':'Search classroom…'}/></div><button className="iconBtn" onClick={()=>setLang(lang==='th'?'en':'th')}><Languages size={16}/><span>{lang.toUpperCase()}</span></button><button className="iconOnly"><Bell size={17}/></button><div className="userPill"><div className="avatar small">{user.name.slice(0,1)}</div><span>{user.name}</span></div></div></header>
   <div className="content">{content}</div>
  </main>
  {toast&&<div className="toast"><CircleCheck size={17}/>{toast}</div>}
 </div>;
}

function AuthScreen({onLogin,store,update}:{onLogin:(u:User)=>void;store:Store;update:(fn:(s:Store)=>void)=>void}){
 const [mode,setMode]=useState<'login'|'signup'|'join'>('login'); const [loginRole,setLoginRole]=useState<'student'|'admin'>('student'); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [name,setName]=useState(''); const [code,setCode]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [show,setShow]=useState(false);
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');setBusy(true);try{
   if(supabase){
    if(mode==='signup'){const {data,error}=await supabase.auth.signUp({email,password,options:{data:{display_name:name}}});if(error)throw error;if(data.user){const u={id:data.user.id,name:name||email.split('@')[0],email,roles:['student'] as Role[]};onLogin(u)}}
    else {const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;let roles:Role[]=['student']; let display=(data.user?.user_metadata?.display_name as string)||email.split('@')[0]; if(data.user){try{const q=await supabase.from('classroom_members').select('roles,display_name').eq('user_id',data.user.id).eq('is_active',true).limit(1).maybeSingle(); if(q.data?.roles?.length)roles=q.data.roles as Role[]; if(q.data?.display_name)display=q.data.display_name;}catch{}} const u={id:data.user?.id||uid(),name:display,email,roles};onLogin(u)}
   } else {
    if(mode==='login'){const admin=loginRole==='admin';const localName=admin?'Admin / Owner':'Student';onLogin({id:uid(),name:localName,email:email||`${admin?'admin':'student'}@class.local`,roles:admin?['owner','admin']:['student']})}
    else if(mode==='signup'){if(!email||!password||!name)throw new Error('กรอกข้อมูลให้ครบ');onLogin({id:uid(),name,email,roles:['student']});}
    else {if(!code.trim())throw new Error('ใส่ Class Code ก่อน');if(store.classroom.code&&code.trim().toUpperCase()!==store.classroom.code.toUpperCase())throw new Error('Class Code ไม่ถูกต้อง');const u={id:uid(),name:name||'Student',email:email||'student@class.local',roles:['student'] as Role[]};update(s=>s.members.push({id:u.id,name:u.name,email:u.email,roles:u.roles,joined_at:isoNow()}));onLogin(u)}
   }
  }catch(err){setError(err instanceof Error?err.message:'เข้าสู่ระบบไม่สำเร็จ')}finally{setBusy(false)}};
 return <div className="authShell"><div className="authVisual" style={store.classroom.coverUrl?{backgroundImage:`linear-gradient(180deg,rgba(18,24,19,.1),rgba(18,24,19,.75)),url(${store.classroom.coverUrl})`}:undefined}><div className="authBrand"><div className="brandMark">C</div><b>CLASSROOM OS</b></div><div className="authQuote"><span>THE DIGITAL HOME<br/>OF YOUR CLASS.</span><p>เรียน · แชร์ · ทำงาน · เติบโตไปด้วยกัน</p></div></div><div className="authPanel"><div className="authTop"><span>{mode==='login'?'WELCOME BACK':mode==='signup'?'CREATE ACCOUNT':'JOIN YOUR CLASS'}</span><div className="authDots"><i/><i/><i/></div></div><div className="loginMode"><button className={loginRole==='student'?'active':''} onClick={()=>{setLoginRole('student');setMode('login')}}>Student / Member</button><button className={loginRole==='admin'?'active':''} onClick={()=>{setLoginRole('admin');setMode('login')}}>Admin / Owner</button></div><h1>{mode==='login'?'กลับเข้าห้องเรียน':mode==='signup'?'สร้างบัญชีนักเรียน':'เข้าร่วมห้องเรียน'}</h1><p className="muted">{mode==='join'?'ใช้ Class Code ที่ Admin ให้มา':'เข้าสู่ CLASSROOM OS เพื่อเข้าถึงข้อมูลของห้อง'}</p>{error&&<div className="errorBox"><AlertTriangle size={16}/>{error}</div>}<form onSubmit={submit} className="authForm">
  {(mode!=='login')&&<Field label="ชื่อที่แสดง" value={name} onChange={setName} placeholder="เช่น Taro"/>}
  {mode==='join'&&<Field label="CLASS CODE" value={code} onChange={v=>setCode(v.toUpperCase())} placeholder="เช่น SCI61"/>}
  <Field label="EMAIL" value={email} onChange={setEmail} placeholder="you@example.com" type="email"/>
  {mode!=='join'&&<div className="passwordField"><Field label="PASSWORD" value={password} onChange={setPassword} placeholder="อย่างน้อย 6 ตัวอักษร" type={show?'text':'password'}/><button type="button" onClick={()=>setShow(!show)}>{show?<EyeOff size={16}/>:<Eye size={16}/>}</button></div>}
  <button className="primary full" disabled={busy}>{busy?'กำลังทำรายการ…':mode==='login'?'เข้าสู่ระบบ':mode==='signup'?'สร้างบัญชี':'เข้าร่วมห้อง'}<ArrowRight size={17}/></button>
 </form><div className="authLinks">{mode==='login'?<><button onClick={()=>setMode('signup')}>สร้างบัญชีใหม่</button><button onClick={()=>setMode('join')}>มี Class Code?</button></>:<button onClick={()=>setMode('login')}>กลับไปเข้าสู่ระบบ</button>}</div><div className="demoNote"><CircleAlert size={15}/><span>{supabase?'เชื่อมต่อ Supabase Auth':'โหมดทดลอง: เลือก Student หรือ Admin / Owner ด้านบนได้เลย'}</span></div></div></div>
}

function NavButton({n,active,onClick}:{n:{p:Page;icon:LucideIcon};active:boolean;onClick:()=>void;key?:string}){const I=n.icon;return <button className={`navBtn ${active?'active':''}`} onClick={onClick}><I size={17}/><span>{th[n.p]}</span>{n.p==='Admin Center'&&<ShieldCheck size={13}/>}</button>}
function PageHead({title,desc,children}:{title:string;desc?:string;children?:React.ReactNode}){return <div className="pageHead"><div><div className="eyebrow">CLASSROOM OS</div><h1>{title}</h1>{desc&&<p>{desc}</p>}</div>{children&&<div className="pageActions">{children}</div>}</div>}
function Empty({icon:Icon=FolderOpen,title,desc,action}:{icon?:LucideIcon;title:string;desc:string;action?:React.ReactNode}){return <div className="empty"><div className="emptyIcon"><Icon size={25}/></div><h3>{title}</h3><p>{desc}</p>{action}</div>}
function Field({label,value,onChange,placeholder='',type='text',options}:{label:string;value:any;onChange:(v:string)=>void;placeholder?:string;type?:string;options?:string[];key?:string}){return <label className="field"><span>{label}</span>{options?<select value={value||''} onChange={e=>onChange(e.target.value)}><option value="">เลือก…</option>{options.map(o=><option key={o} value={o}>{o}</option>)}</select>:type==='textarea'?<textarea value={value||''} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>:<input type={type} value={value||''} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>}</label>}
function Modal({title,onClose,children,wide=false}:{title:string;onClose:()=>void;children:React.ReactNode;wide?:boolean}){return <div className="modalBackdrop"><div className={`modal ${wide?'wide':''}`}><div className="modalHead"><div><span>CLASSROOM OS</span><h2>{title}</h2></div><button onClick={onClose}><X/></button></div><div className="modalBody">{children}</div></div></div>}

function HomePage({store,user,go,lang}:{store:Store;user:User;go:(p:Page)=>void;lang:Lang}){
 const next=store.schedules.find(x=>x.day===['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][new Date().getDay()]); const upcoming: Row[]=[...store.tasks.map(x=>({...x,_type:'งาน'} as Row)),...store.exams.map(x=>({...x,_type:'สอบ'} as Row)),...store.events.map(x=>({...x,_type:'กิจกรรม'} as Row))].filter((x:Row)=>x.due||x.date).slice(0,4);
 return <div className="home"><section className="hero" style={store.classroom.coverUrl?{backgroundImage:`linear-gradient(90deg,rgba(18,23,18,.72),rgba(18,23,18,.18)),url(${store.classroom.coverUrl})`}:undefined}><div className="heroCopy"><span className="heroKicker">{store.classroom.program||'CLASSROOM OS'}</span><h1>{store.classroom.name||'YOUR CLASS'}</h1><p>{store.classroom.year||'ยังไม่ได้ตั้งค่าข้อมูลห้อง'} {store.classroom.code&&`· ${store.classroom.code}`}</p></div><button className="heroEdit" onClick={()=>go('Class Setup')}>Edit class <Edit3 size={15}/></button></section><div className="greeting"><div><span>GOOD MORNING,</span><h2>{user.name.toUpperCase()}.</h2></div><div className="dateStamp">{new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'})}</div></div><div className="homeGrid"><section className="nextCard panel"><div className="sectionLabel">NEXT CLASS</div>{next?<><div className="nextTime">{next.start} <span>—</span> {next.end}</div><h2>{next.subject||'วิชา'}</h2><p>{next.room||'ไม่ระบุห้อง'}</p></>:<Empty icon={Clock3} title="ยังไม่มีคาบถัดไป" desc="Admin สามารถเพิ่มตารางเรียนได้จาก Class Setup" action={<button className="textBtn" onClick={()=>go('Schedule')}>ดูตารางเรียน <ArrowRight size={14}/></button>}/>}</section><section className="panel pulseMini"><div className="panelTitle"><span>CLASS PULSE</span><button onClick={()=>go('Class Pulse')}>ดูทั้งหมด</button></div><div className="miniMetrics"><Metric n="สมาชิก" v={store.members.length}/><Metric n="งาน" v={store.tasks.length}/><Metric n="สอบ" v={store.exams.length}/><Metric n="ไฟล์" v={store.files.length}/></div></section></div><section className="homeSection"><div className="sectionHeader"><div><span className="sectionLabel">DON'T FORGET</span><h2>สิ่งที่กำลังจะมาถึง</h2></div><button className="textBtn" onClick={()=>go('Calendar')}>ดูปฏิทิน <ArrowRight size={14}/></button></div>{upcoming.length?<div className="upcomingList">{upcoming.map((x,i)=><div className="upcoming" key={i}><div className="upDate">{formatDate(x.due||x.date)}</div><div className="upMain"><span>{x._type}</span><b>{x.title}</b></div><ChevronRight size={17}/></div>)}</div>:<Empty icon={CalendarDays} title="ยังไม่มีรายการ" desc="เมื่อ Admin เพิ่มงาน สอบ หรือกิจกรรม รายการจะปรากฏตรงนี้"/>}</section><section className="homeSplit"><div className="panel featureStory"><div className="sectionLabel">CLASS FILES</div><h2>คลังความรู้ของห้อง</h2><p>แชร์ PDF ชีทสรุป รูป และเอกสารให้เพื่อนในห้องเข้าถึงได้จากที่เดียว</p><button className="primary" onClick={()=>go('Class Files')}>เปิด Class Files <ArrowRight size={16}/></button></div><div className="panel momentStory"><div className="sectionLabel">CLASS MOMENTS</div>{store.gallery[0]?.url?<img src={store.gallery[0].url}/>:<div className="momentPlaceholder"><Images size={28}/><span>เริ่มเก็บความทรงจำของห้อง</span></div>}<button className="storyLink" onClick={()=>go('Gallery')}>ดู Moments <ArrowRight size={14}/></button></div></section></div>
}
function Metric({n,v}:{n:string;v:any}){return <div><span>{n}</span><b>{v}</b></div>}

function AdminCenter({store,user,go,lang}:{store:Store;user:User;go:(p:Page)=>void;lang:Lang}){
 const checks=[['ข้อมูลห้องเรียน','Class Setup',!!store.classroom.name],['สมาชิก','Members',store.members.length>0],['วิชา','Subjects',store.subjects.length>0],['ตารางเรียน','Schedule',store.schedules.length>0],['ประกาศ','Announcements',store.announcements.length>0],['Class Files','Class Files',true]] as [string,Page,boolean][];return <div><PageHead title="Admin Control Center" desc="จัดการทุกอย่างของห้องจากที่เดียว — ไม่ต้องแก้โค้ด"><span className="roleBadge"><ShieldCheck size={15}/> {roleLabel[user.roles[0]]}</span></PageHead><div className="adminHero"><div><span>COMMAND CENTER</span><h2>{store.classroom.name||'ตั้งค่าห้องของคุณ'}</h2><p>{store.classroom.program||'เริ่มต้นด้วยการตั้งค่าข้อมูลพื้นฐาน แล้วค่อยเติมระบบที่ต้องการใช้'}</p></div><button className="primary" onClick={()=>go('Class Setup')}>ตั้งค่าห้อง <ArrowRight size={16}/></button></div><div className="adminGrid"><div className="panel setupPanel"><div className="panelTitle"><span>SETUP CHECKLIST</span><span>{checks.filter(x=>x[2]).length}/{checks.length}</span></div>{checks.map(([name,p,ok])=><button className="setupRow" key={p} onClick={()=>go(p)}><span className={ok?'check done':'check'}>{ok?<Check size={13}/>:''}</span><div><b>{name}</b><small>{ok?'พร้อมใช้งาน':'ต้องตั้งค่า'}</small></div><ChevronRight size={16}/></button>)}</div><div className="panel adminStats"><div className="panelTitle"><span>OVERVIEW</span></div><div className="adminMetricGrid"><Metric n="Members" v={store.members.length}/><Metric n="Subjects" v={store.subjects.length}/><Metric n="Tasks" v={store.tasks.length}/><Metric n="Files" v={store.files.length}/><Metric n="Messages" v={store.messages.length}/><Metric n="Events" v={store.events.length}/></div></div></div><div className="adminModules"><AdminModule icon={Users} title="Members & Roles" desc="เพิ่มสมาชิกและกำหนดหลาย Role" onClick={()=>go('Members')}/><AdminModule icon={GraduationCap} title="Academic" desc="วิชา · ตารางเรียน · งาน · สอบ" onClick={()=>go('Subjects')}/><AdminModule icon={FolderOpen} title="Class Files" desc="คลัง PDF ชีท และเอกสารของห้อง" onClick={()=>go('Class Files')}/><AdminModule icon={Brush} title="Duty Manager" desc="เวร · สลับเวร · ขออนุมัติ" onClick={()=>go('Duty')}/><AdminModule icon={MessageCircle} title="Community" desc="Channels · Chat · Poll" onClick={()=>go('Community')}/><AdminModule icon={SlidersHorizontal} title="Feature Control" desc="เปิด/ปิดโมดูลเพื่อลดความรก" onClick={()=>go('Feature Control')}/></div></div>
}
function AdminModule({icon:Icon,title,desc,onClick}:{icon:LucideIcon;title:string;desc:string;onClick:()=>void}){return <button className="adminModule" onClick={onClick}><div className="moduleIcon"><Icon size={19}/></div><div><b>{title}</b><span>{desc}</span></div><ArrowRight size={16}/></button>}

function ClassSetup({store,update,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const [f,setF]=useState(store.classroom);const [saved,setSaved]=useState(false);return <div><PageHead title="ตั้งค่าห้องเรียน" desc="ข้อมูลตรงนี้จะถูกนำไปใช้ทั่วทั้ง CLASSROOM OS"><button className="primary" onClick={()=>{update(s=>s.classroom={...f});log('updated','classroom');setSaved(true);notify('บันทึกข้อมูลห้องแล้ว')}}><Save size={16}/> บันทึก</button></PageHead><div className="setupLayout"><div className="panel setupForm"><div className="panelTitle"><span>CLASS IDENTITY</span></div><div className="formGrid two"><Field label="ชื่อห้องเรียน" value={f.name} onChange={v=>setF({...f,name:v})} placeholder="เช่น 6/1"/><Field label="แผนการเรียน" value={f.program} onChange={v=>setF({...f,program:v})} placeholder="เช่น SCIENCE PROGRAM"/><Field label="ปีการศึกษา" value={f.year} onChange={v=>setF({...f,year:v})} placeholder="2026"/><Field label="CLASS CODE" value={f.code} onChange={v=>setF({...f,code:v.toUpperCase()})} placeholder="SCI61"/><Field label="Theme" value={f.theme} onChange={v=>setF({...f,theme:v})} options={['sage','sand','sky','lavender','terracotta']}/><Field label="Humor Mode" value={f.humor} onChange={v=>setF({...f,humor:v})} options={['off','friendly','chaos']}/></div><Field label="คำอธิบายห้อง" value={f.description} onChange={v=>setF({...f,description:v})} type="textarea" placeholder="เล่าเกี่ยวกับห้องสั้น ๆ"/></div><div className="panel setupVisual"><div className="panelTitle"><span>CLASS COVER</span></div><div className="coverPreview" style={f.coverUrl?{backgroundImage:`url(${f.coverUrl})`}:undefined}><div><ImagePlus size={23}/><span>{f.coverUrl?'เปลี่ยนรูปปก':'ใส่รูปปกห้อง'}</span></div></div><Field label="Cover image URL" value={f.coverUrl} onChange={v=>setF({...f,coverUrl:v})} placeholder="https://…"/><Field label="Logo image URL" value={f.logoUrl} onChange={v=>setF({...f,logoUrl:v})} placeholder="https://…"/>{saved&&<div className="successBox"><CircleCheck size={16}/> Saved</div>}</div></div></div>}

function SubjectsPage({store,update,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const u=loadUser();const canWrite=can(u,['owner','admin','teacher']);return <CrudPage title="Subjects" desc="จัดการรายวิชาและครูผู้สอน" icon={GraduationCap} rows={store.subjects} fields={[['name','ชื่อวิชา'],['code','รหัสวิชา'],['teacher','ครูผู้สอน'],['color','สี'],]} options={{color:['violet','green','amber','red','blue']}} canWrite={canWrite} add={(r)=>{update(s=>s.subjects.push({...r,id:uid()}));log('created','subject');notify('เพิ่มวิชาแล้ว')}} del={(id)=>{update(s=>s.subjects=s.subjects.filter(x=>x.id!==id));notify('ลบวิชาแล้ว')}}/>}
function CrudPage({title,desc,icon:Icon,rows,fields,options={},add,del,customAction,canWrite=true}:{title:string;desc?:string;icon:LucideIcon;rows:Row[];fields:[string,string][];options?:Record<string,string[]>;add:(r:Row)=>void;del:(id:string)=>void;customAction?:(r:Row)=>React.ReactNode;canWrite?:boolean}){const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({});return <div><PageHead title={title} desc={desc}>{canWrite&&<button className="primary" onClick={()=>{setF({});setOpen(true)}}><Plus size={16}/> เพิ่ม</button>}</PageHead><div className="panel tablePanel">{rows.length?<div className="dataTable"><div className="tableHead">{fields.map(([k,l])=><span key={k}>{l}</span>)}<span/></div>{rows.map(r=><div className="tableRow" key={r.id}>{fields.map(([k])=><div key={k}>{k==='color'?<span className={`colorDot ${r[k]||'sage'}`}/>:<><b>{r[k]||'—'}</b>{k==='email'&&<small>{r.email}</small>}</>}</div>)}<div className="rowActions">{customAction?.(r)}{canWrite&&<button className="dangerIcon" onClick={()=>del(r.id)}><Trash2 size={15}/></button>}</div></div>)}</div>:<Empty icon={Icon} title="ยังไม่มีข้อมูล" desc="ข้อมูลที่ Admin เพิ่มจะแสดงตรงนี้" action={<button className="secondary" onClick={()=>setOpen(true)}><Plus size={15}/> เพิ่มรายการแรก</button>}/>}</div>{open&&<Modal title={`เพิ่ม ${title}`} onClose={()=>setOpen(false)}><div className="formGrid two">{fields.map(([k,l])=><Field key={k} label={l} value={f[k]} onChange={v=>setF({...f,[k]:v})} options={options[k]}/>)}</div><button className="primary full" onClick={()=>{if(!fields.some(([k])=>String(f[k]||'').trim()))return;add(f);setOpen(false)}}>บันทึก <Save size={16}/></button></Modal>}</div>}

function SchedulePage({store,update,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(loadUser(),['owner','admin','teacher']);const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({day:'Mon'});const days=[['Mon','จันทร์'],['Tue','อังคาร'],['Wed','พุธ'],['Thu','พฤหัส'],['Fri','ศุกร์']];return <div><PageHead title="ตารางเรียน" desc="Admin เป็นคนกรอกตารางจริงของห้อง">{canWrite&&<button className="primary" onClick={()=>setOpen(true)}><Plus size={16}/> เพิ่มคาบเรียน</button>}</PageHead><div className="scheduleBoard">{days.map(([d,thd])=><div className="dayColumn" key={d}><div className="dayHeader"><b>{thd}</b><span>{d}</span></div>{store.schedules.filter(x=>x.day===d).sort((a,b)=>a.start.localeCompare(b.start)).map(x=><div className="classSlot" key={x.id}><span>{x.start} — {x.end}</span><b>{x.subject||'วิชา'}</b><small>{x.room||'—'}</small>{canWrite&&<button onClick={()=>{update(s=>s.schedules=s.schedules.filter(y=>y.id!==x.id));notify('ลบคาบเรียนแล้ว')}}><Trash2 size={13}/></button>}</div>)}{!store.schedules.some(x=>x.day===d)&&<span className="dayEmpty">ว่าง</span>}</div>)}</div>{open&&<Modal title="เพิ่มคาบเรียน" onClose={()=>setOpen(false)}><div className="formGrid two"><Field label="วัน" value={f.day} onChange={v=>setF({...f,day:v})} options={days.map(x=>x[0])}/><Field label="วิชา" value={f.subject} onChange={v=>setF({...f,subject:v})} placeholder="ชื่อวิชา"/><Field label="เริ่ม" value={f.start} onChange={v=>setF({...f,start:v})} type="time"/><Field label="จบ" value={f.end} onChange={v=>setF({...f,end:v})} type="time"/><Field label="ห้อง" value={f.room} onChange={v=>setF({...f,room:v})} placeholder="401"/></div><button className="primary full" onClick={()=>{if(!f.subject||!f.start||!f.end)return;update(s=>s.schedules.push({...f,id:uid()}));log('created','schedule');notify('เพิ่มคาบเรียนแล้ว');setOpen(false);setF({day:'Mon'})}}>บันทึก</button></Modal>}</div>}

function TasksPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(user,['owner','admin','teacher']);const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({priority:'normal'});const toggle=(id:string)=>update(s=>{const x=s.tasks.find(t=>t.id===id);if(x){x.done=!x.done;x.completed_by=x.done?user.id:null}});return <div><PageHead title="Tasks" desc="งานของห้องและสถานะการทำงาน">{canWrite&&<button className="primary" onClick={()=>setOpen(true)}><Plus size={16}/> เพิ่มงาน</button>}</PageHead><div className="taskList">{store.tasks.length?store.tasks.map(t=><div className={`taskItem ${t.done?'done':''}`} key={t.id}><button className="checkButton" onClick={()=>toggle(t.id)}>{t.done?<Check size={15}/>:''}</button><div className="taskInfo"><b>{t.title}</b><span>{t.subject||'ทั่วไป'} · {t.due?formatDate(t.due):'ไม่กำหนด'}</span></div><span className={`priority ${t.priority}`}>{t.priority}</span>{canWrite&&<button className="dangerIcon" onClick={()=>{update(s=>s.tasks=s.tasks.filter(x=>x.id!==t.id));notify('ลบงานแล้ว')}}><Trash2 size={15}/></button>} </div>):<Empty icon={CheckSquare} title="ยังไม่มีงาน" desc="Admin เพิ่มงานได้ แล้วสมาชิกจะเห็นตรงนี้" action={canWrite?<button className="secondary" onClick={()=>setOpen(true)}><Plus size={15}/> สร้างงาน</button>:undefined}/>}</div>{open&&<Modal title="เพิ่มงาน" onClose={()=>setOpen(false)}><div className="formGrid two"><Field label="ชื่องาน" value={f.title} onChange={v=>setF({...f,title:v})} placeholder="เช่น รายงานชีวะ"/><Field label="วิชา" value={f.subject} onChange={v=>setF({...f,subject:v})}/><Field label="กำหนดส่ง" value={f.due} onChange={v=>setF({...f,due:v})} type="datetime-local"/><Field label="ความสำคัญ" value={f.priority} onChange={v=>setF({...f,priority:v})} options={['low','normal','high','urgent']}/></div><Field label="รายละเอียด" value={f.description} onChange={v=>setF({...f,description:v})} type="textarea"/><button className="primary full" onClick={()=>{if(!f.title)return;update(s=>s.tasks.unshift({...f,id:uid(),created_by:user.id,created_at:isoNow(),done:false}));log('created','task');notify('เพิ่มงานแล้ว');setOpen(false);setF({priority:'normal'})}}>บันทึก</button></Modal>}</div>}

function ExamsPage({store,update,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(loadUser(),['owner','admin','teacher']); const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({});return <div><PageHead title="Exams" desc="ตารางสอบและหัวข้อที่ต้องอ่าน">{canWrite&&<button className="primary" onClick={()=>setOpen(true)}><Plus size={16}/> เพิ่มการสอบ</button>}</PageHead><div className="examGrid">{store.exams.length?store.exams.map(x=><div className="examCard" key={x.id}><div className="examDate">{formatDate(x.date)}</div><div><span>{x.subject||'วิชา'}</span><h3>{x.title}</h3><p>{x.topics||'ยังไม่มีหัวข้อ'}</p><small>{x.room||'ไม่ระบุห้อง'}</small></div>{canWrite&&<button className="dangerIcon" onClick={()=>{update(s=>s.exams=s.exams.filter(y=>y.id!==x.id));notify('ลบการสอบแล้ว')}}><Trash2 size={15}/></button>} </div>):<Empty icon={FileText} title="ยังไม่มีการสอบ" desc="Admin สามารถเพิ่มตารางสอบและหัวข้อได้"/>}</div>{open&&<Modal title="เพิ่มการสอบ" onClose={()=>setOpen(false)}><div className="formGrid two"><Field label="ชื่อการสอบ" value={f.title} onChange={v=>setF({...f,title:v})}/><Field label="วิชา" value={f.subject} onChange={v=>setF({...f,subject:v})}/><Field label="วันและเวลา" value={f.date} onChange={v=>setF({...f,date:v})} type="datetime-local"/><Field label="ห้อง" value={f.room} onChange={v=>setF({...f,room:v})}/></div><Field label="หัวข้อสอบ" value={f.topics} onChange={v=>setF({...f,topics:v})} type="textarea"/><button className="primary full" onClick={()=>{if(!f.title||!f.date)return;update(s=>s.exams.push({...f,id:uid()}));log('created','exam');notify('เพิ่มการสอบแล้ว');setOpen(false);setF({})}}>บันทึก</button></Modal>}</div>}

function CalendarPage({store}:{store:Store}){const items=[...store.tasks.map(x=>({type:'งาน',title:x.title,date:x.due})),...store.exams.map(x=>({type:'สอบ',title:x.title,date:x.date})),...store.events.map(x=>({type:'กิจกรรม',title:x.title,date:x.date}))].filter(x=>x.date).sort((a,b)=>String(a.date).localeCompare(String(b.date)));return <div><PageHead title="Calendar" desc="รวมงาน สอบ และกิจกรรมจากข้อมูลจริงของห้อง"/><div className="calendarTimeline">{items.length?items.map((x,i)=><div className="calendarItem" key={i}><div className="calendarRail"><span>{new Date(x.date).getDate()}</span><small>{new Date(x.date).toLocaleDateString('en-US',{month:'short'})}</small></div><div><span className="calendarType">{x.type}</span><h3>{x.title}</h3><p>{formatDateTime(x.date)}</p></div></div>):<Empty icon={CalendarDays} title="ปฏิทินยังว่าง" desc="เพิ่มงาน สอบ หรือกิจกรรมเพื่อเริ่มใช้ปฏิทิน"/>}</div></div>}

function EventsPage({store,update,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(loadUser(),['owner','admin']); const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({});return <div><PageHead title="Events" desc="กิจกรรมของห้อง">{canWrite&&<button className="primary" onClick={()=>setOpen(true)}><Plus size={16}/> สร้างกิจกรรม</button>}</PageHead><div className="eventGrid">{store.events.length?store.events.map(x=><div className="eventCard" key={x.id}><div className="eventImage"><PartyPopper size={23}/></div><div className="eventBody"><span>{formatDate(x.date)} · {x.location||'สถานที่ไม่ระบุ'}</span><h3>{x.title}</h3><p>{x.description||'ไม่มีรายละเอียด'}</p></div>{canWrite&&<button className="dangerIcon" onClick={()=>{update(s=>s.events=s.events.filter(y=>y.id!==x.id));notify('ลบกิจกรรมแล้ว')}}><Trash2 size={15}/></button>} </div>):<Empty icon={PartyPopper} title="ยังไม่มีกิจกรรม" desc="สร้างกิจกรรมสำหรับห้องได้จากปุ่มด้านบน"/>}</div>{open&&<Modal title="สร้างกิจกรรม" onClose={()=>setOpen(false)}><div className="formGrid two"><Field label="ชื่อกิจกรรม" value={f.title} onChange={v=>setF({...f,title:v})}/><Field label="วันและเวลา" value={f.date} onChange={v=>setF({...f,date:v})} type="datetime-local"/><Field label="สถานที่" value={f.location} onChange={v=>setF({...f,location:v})}/></div><Field label="รายละเอียด" value={f.description} onChange={v=>setF({...f,description:v})} type="textarea"/><button className="primary full" onClick={()=>{if(!f.title||!f.date)return;update(s=>s.events.push({...f,id:uid()}));log('created','event');notify('สร้างกิจกรรมแล้ว');setOpen(false);setF({})}}>บันทึก</button></Modal>}</div>}

function AnnouncementsPage({store,update,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(loadUser(),['owner','admin']); const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({pinned:false});return <div><PageHead title="Announcements" desc="ประกาศสำคัญของห้อง">{canWrite&&<button className="primary" onClick={()=>setOpen(true)}><Plus size={16}/> สร้างประกาศ</button>}</PageHead><div className="announcementList">{store.announcements.length?store.announcements.map(x=><article className={`announcement ${x.pinned?'pinned':''}`} key={x.id}><div className="annIcon"><Megaphone size={19}/></div><div><div className="annMeta">{x.pinned&&<span><Pin size={12}/> PINNED</span>} {formatDateTime(x.created_at)}</div><h3>{x.title}</h3><p>{x.body}</p></div>{canWrite&&<button className="dangerIcon" onClick={()=>{update(s=>s.announcements=s.announcements.filter(y=>y.id!==x.id));notify('ลบประกาศแล้ว')}}><Trash2 size={15}/></button>} </article>):<Empty icon={Megaphone} title="ยังไม่มีประกาศ" desc="ใช้หน้านี้เป็นกระดานประกาศของห้อง"/>}</div>{open&&<Modal title="สร้างประกาศ" onClose={()=>setOpen(false)}><Field label="หัวข้อ" value={f.title} onChange={v=>setF({...f,title:v})}/><Field label="เนื้อหา" value={f.body} onChange={v=>setF({...f,body:v})} type="textarea"/><label className="checkLine"><input type="checkbox" checked={!!f.pinned} onChange={e=>setF({...f,pinned:e.target.checked})}/> ปักหมุดประกาศ</label><button className="primary full" onClick={()=>{if(!f.title||!f.body)return;update(s=>s.announcements.unshift({...f,id:uid(),created_at:isoNow()}));log('created','announcement');notify('เผยแพร่ประกาศแล้ว');setOpen(false);setF({pinned:false})}}>เผยแพร่ <Send size={16}/></button></Modal>}</div>}

function DutyPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(loadUser(),['owner','admin','duty_manager']); const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({status:'pending'});const [filter,setFilter]=useState('all');const members=store.members.length?store.members:[{id:user.id,name:user.name}];return <div><PageHead title="Duty Wall" desc="ตารางเวรที่ Admin จัดให้ และสมาชิกอัปเดตสถานะได้">{canWrite&&<button className="primary" onClick={()=>setOpen(true)}><Plus size={16}/> เพิ่มเวร</button>}</PageHead><div className="dutyFilters"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>ทั้งหมด</button><button className={filter==='pending'?'active':''} onClick={()=>setFilter('pending')}>รอดำเนินการ</button><button className={filter==='completed'?'active':''} onClick={()=>setFilter('completed')}>เสร็จแล้ว</button></div><div className="dutyGrid">{store.duties.filter(x=>filter==='all'||x.status===filter).length?store.duties.filter(x=>filter==='all'||x.status===filter).map(x=><div className="dutyCard" key={x.id}><div className="dutyDate">{formatDate(x.date)}</div><div><span>{x.status}</span><h3>{x.title}</h3><p>{x.assignee||'ยังไม่มีผู้รับผิดชอบ'}</p></div><button className="checkButton" onClick={()=>{update(s=>{const d=s.duties.find(y=>y.id===x.id);if(d)d.status=d.status==='completed'?'pending':'completed'});notify('อัปเดตสถานะเวรแล้ว')}}>{x.status==='completed'?<Check size={15}/>:''}</button>{canWrite&&<button className="dangerIcon" onClick={()=>{update(s=>s.duties=s.duties.filter(y=>y.id!==x.id));notify('ลบเวรแล้ว')}}><Trash2 size={15}/></button>}</div>):<Empty icon={Brush} title="ยังไม่มีเวร" desc="Admin สร้างตารางเวรแล้วสมาชิกจะเห็นตรงนี้"/>}</div>{open&&<Modal title="เพิ่มเวร" onClose={()=>setOpen(false)}><div className="formGrid two"><Field label="วันที่" value={f.date} onChange={v=>setF({...f,date:v})} type="date"/><Field label="งานเวร" value={f.title} onChange={v=>setF({...f,title:v})} placeholder="เช่น กวาดห้อง"/><Field label="ผู้รับผิดชอบ" value={f.assignee} onChange={v=>setF({...f,assignee:v})} options={members.map((m:any)=>m.name)}/></div><Field label="หมายเหตุ" value={f.note} onChange={v=>setF({...f,note:v})}/><button className="primary full" onClick={()=>{if(!f.title||!f.date)return;update(s=>s.duties.push({...f,id:uid(),status:'pending'}));log('created','duty');notify('เพิ่มเวรแล้ว');setOpen(false);setF({status:'pending'})}}>บันทึก</button></Modal>}</div>}

function WeeklyPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(user,['owner','admin','reporter']);const [text,setText]=useState('');const publish=()=>{if(!text.trim())return;update(s=>s.weekly.unshift({id:uid(),title:'THE CLASSROOM WEEKLY',text,date:isoNow(),author:user.name}));log('published','weekly');notify('เผยแพร่ Weekly แล้ว');setText('')};return <div><PageHead title="THE CLASSROOM WEEKLY" desc="พื้นที่สำหรับ Reporter สรุปเรื่องราวประจำสัปดาห์">{canWrite&&<button className="primary" onClick={publish}><Send size={16}/> Publish</button>}</PageHead><div className="weeklyLayout"><div className="panel weeklyEditor"><span className="sectionLabel">EDITOR'S DESK</span><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="เขียนเรื่องราวของสัปดาห์นี้…"/><div className="editorHint">งาน {store.tasks.length} · สอบ {store.exams.length} · กิจกรรม {store.events.length}</div></div><div className="weeklyPaper"><div className="paperMast">THE CLASSROOM WEEKLY <span>NO. {store.weekly.length+1}</span></div><div className="paperDate">{new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</div><h2>{text||'เรื่องราวประจำสัปดาห์ของห้องเรา'}</h2><p>{text?'':'สรุปงาน กิจกรรม ประกาศ และโมเมนต์สำคัญของห้องในรูปแบบ editorial'}</p><div className="paperStats"><span>Tasks <b>{store.tasks.length}</b></span><span>Exams <b>{store.exams.length}</b></span><span>Events <b>{store.events.length}</b></span></div></div></div><div className="panel publishedList"><div className="panelTitle"><span>ARCHIVE</span></div>{store.weekly.length?store.weekly.map(x=><div className="archiveRow" key={x.id}><div><b>{x.title}</b><span>{formatDate(x.date)} · {x.author}</span></div><p>{x.text}</p></div>):<span className="muted">ยังไม่มีฉบับที่เผยแพร่</span>}</div></div>}

function CommunityPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canManage=can(user,['owner','admin','moderator']);const [msg,setMsg]=useState('');const [channel,setChannel]=useState(store.channels[0]?.id||'general');const [newChannel,setNewChannel]=useState(false);const currentMessages=store.messages.filter(m=>m.channel===channel);const send=()=>{if(!msg.trim())return;update(s=>s.messages.push({id:uid(),channel,user:user.name,content:msg,created_at:isoNow()}));log('sent','message');setMsg('')};return <div><PageHead title="Community" desc="พื้นที่พูดคุยของห้อง">{canManage&&<button className="secondary" onClick={()=>setNewChannel(true)}><Plus size={16}/> Channel</button>}</PageHead><div className="communityLayout"><aside className="channelList"><div className="channelHeader">CHANNELS <button onClick={()=>setNewChannel(true)}><Plus size={14}/></button></div>{store.channels.map(c=><button key={c.id} className={channel===c.id?'active':''} onClick={()=>setChannel(c.id)}><Hash size={14}/>{c.name}</button>)}{!store.channels.length&&<div className="channelEmpty">ยังไม่มี channel<br/><button onClick={()=>update(s=>s.channels.push({id:'general',name:'general'}))}>สร้าง #general</button></div>}</aside><section className="chatPanel"><div className="chatHead"><div><span>CHANNEL</span><h3># {store.channels.find(c=>c.id===channel)?.name||'general'}</h3></div><span>{currentMessages.length} messages</span></div><div className="messages">{currentMessages.length?currentMessages.map(m=><div className="message" key={m.id}><div className="avatar">{String(m.user).slice(0,1)}</div><div><div className="messageMeta"><b>{m.user}</b><span>{formatDateTime(m.created_at)}</span></div><p>{m.content}</p></div></div>):<div className="chatEmpty"><MessageSquare size={25}/><b>เริ่มบทสนทนา</b><span>ข้อความใน Channel นี้จะแสดงที่นี่</span></div>}</div><div className="composer"><input value={msg} onChange={e=>setMsg(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="เขียนข้อความ…"/><button onClick={send}><Send size={16}/></button></div></section></div>{newChannel&&<Modal title="สร้าง Channel" onClose={()=>setNewChannel(false)}><Field label="ชื่อ Channel" value={''} onChange={()=>{}} placeholder="เช่น homework"/><button className="primary full" onClick={()=>{const name=prompt('ชื่อ Channel');if(name){update(s=>s.channels.push({id:uid(),name:name.replace(/^#/,'')}));notify('สร้าง Channel แล้ว')}setNewChannel(false)}}>สร้าง</button></Modal>}</div>}

function StudyPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(user,['owner','admin','teacher']);const [active,setActive]=useState<string|null>(null);const [seconds,setSeconds]=useState(25*60);const [running,setRunning]=useState(false);useEffect(()=>{if(!running)return;const i=setInterval(()=>setSeconds(s=>s>0?s-1:0),1000);return()=>clearInterval(i)},[running]);const create=()=>update(s=>s.rooms.push({id:uid(),name:'Study Room',subject:'',topic:'',active:true}));return <div><PageHead title="Study Rooms" desc="อ่านหนังสือร่วมกันและใช้ Focus Timer">{canWrite&&<button className="primary" onClick={create}><Plus size={16}/> สร้างห้อง</button>}</PageHead><div className="studyGrid">{store.rooms.length?store.rooms.map(r=><div className={`studyCard ${active===r.id?'selected':''}`} key={r.id} onClick={()=>setActive(r.id)}><div className="studyIcon"><BookOpen size={21}/></div><span>STUDY ROOM</span><h3>{r.name}</h3><p>{r.subject||'เลือกวิชา'} · {r.topic||'หัวข้อยังไม่ระบุ'}</p><div className="presence"><i/> เปิดอยู่</div></div>):<Empty icon={Timer} title="ยังไม่มี Study Room" desc="สร้างห้องอ่านหนังสือสำหรับกลุ่มได้"/>}</div>{active&&<div className="focusBar panel"><div><span>FOCUS TIMER</span><b>{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</b></div><button className="secondary" onClick={()=>setRunning(!running)}>{running?'Pause':'Start'}</button><button className="iconBtn" onClick={()=>{setRunning(false);setSeconds(25*60)}}><RotateCcw size={16}/></button></div>}</div>}

function FilesPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const input=useRef<HTMLInputElement>(null);const [category,setCategory]=useState('ทั้งหมด');const [q,setQ]=useState('');const [busy,setBusy]=useState(false);const cats=['ทั้งหมด','ชีววิทยา','เคมี','ฟิสิกส์','คณิตศาสตร์','เอกสาร','รูปภาพ'];const upload=async(e:React.ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;setBusy(true);try{let path='';if(supabase){path=`local/${uid()}-${file.name}`;const {error}=await supabase.storage.from('class-files').upload(path,file,{upsert:false});if(error)throw error}else path='local-only';update(s=>s.files.unshift({id:uid(),name:file.name,size:file.size,type:file.type,path,category:file.type.includes('pdf')?'เอกสาร':'ไฟล์',uploader:user.name,created_at:isoNow()}));log('uploaded','file',{name:file.name});notify('แชร์ไฟล์สำเร็จ')}catch(err){notify('อัปโหลดไม่สำเร็จ')}finally{setBusy(false);e.target.value=''}};const filtered=store.files.filter(f=>(category==='ทั้งหมด'||f.category===category)&&String(f.name).toLowerCase().includes(q.toLowerCase()));const download=async(f:Row)=>{if(supabase&&f.path!=='local-only'){const {data}=await supabase.storage.from('class-files').createSignedUrl(f.path,60);if(data?.signedUrl)window.open(data.signedUrl,'_blank');else notify('เปิดไฟล์ไม่สำเร็จ')}else notify('ไฟล์นี้อยู่ใน Local Mode — เชื่อม Supabase เพื่อดาวน์โหลดข้ามเครื่อง')};return <div><PageHead title="Class Files" desc="Google Drive สำหรับห้อง — แชร์ชีทสรุป PDF และเอกสารให้เพื่อน"><label className="primary uploadBtn"><Upload size={16}/>{busy?'กำลังอัปโหลด…':'แชร์ไฟล์'}<input ref={input} type="file" hidden onChange={upload}/></label></PageHead><div className="fileToolbar"><div className="filterChips">{cats.map(c=><button className={category===c?'active':''} key={c} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="inlineSearch"><Search size={15}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="ค้นหาไฟล์…"/></div></div><div className="fileNotice"><FolderOpen size={19}/><div><b>Private class library</b><span>{supabase?'ไฟล์เชื่อม Supabase Storage':'ตอนนี้อยู่ Local Mode — ตั้งค่า Supabase เพื่อแชร์ไฟล์จริงข้ามเครื่อง'}</span></div></div><div className="fileGrid">{filtered.length?filtered.map(f=><div className="fileCard" key={f.id}><div className="fileIcon"><FileText/></div><div className="fileMeta"><b>{f.name}</b><span>{f.category} · {formatSize(f.size)}</span><small>{f.uploader||'สมาชิก'} · {formatDate(f.created_at)}</small></div><button className="downloadBtn" onClick={()=>download(f)}><Download size={16}/></button></div>):<Empty icon={FolderOpen} title="ยังไม่มีไฟล์" desc="กด แชร์ไฟล์ เพื่อเพิ่มเอกสารแรกของห้อง" action={<label className="secondary uploadBtn"><Upload size={15}/> แชร์ไฟล์<input type="file" hidden onChange={upload}/></label>}/>}</div></div>}

function GalleryPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canDelete=can(user,['owner','admin']);const [url,setUrl]=useState('');const add=()=>{if(!url)return;update(s=>s.gallery.unshift({id:uid(),url,caption:'',album:'Class Moments',uploader:user.name,created_at:isoNow()}));log('added','gallery');notify('เพิ่มรูปแล้ว');setUrl('')};return <div><PageHead title="Class Moments" desc="ตกแต่งพื้นที่ของห้องด้วยรูปกิจกรรมและความทรงจำ"><div className="pageActions"><input className="quickInput" value={url} onChange={e=>setUrl(e.target.value)} placeholder="วาง image URL…"/><button className="primary" onClick={add}><ImagePlus size={16}/> เพิ่มรูป</button></div></PageHead>{store.gallery.length?<div className="galleryGrid">{store.gallery.map(x=><figure key={x.id}><img src={x.url} onError={e=>{(e.currentTarget as HTMLImageElement).style.display='none'}}/><figcaption><b>{x.caption||'Class Moment'}</b><span>{x.uploader} · {formatDate(x.created_at)}</span></figcaption>{(canDelete||x.uploader===user.name)&&<button className="dangerIcon" onClick={()=>update(s=>s.gallery=s.gallery.filter(y=>y.id!==x.id))}><Trash2 size={14}/></button>}</figure>)}</div>:<Empty icon={Images} title="ยังไม่มีรูป" desc="เพิ่มรูปกิจกรรมของห้องด้วย URL รูปภาพ หรือเชื่อม Storage ภายหลัง"/>}</div>}

function FundPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(user,['owner','admin','treasurer']);const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({type:'income'});const balance=store.transactions.reduce((a,x)=>a+(x.type==='income'?Number(x.amount):-(Number(x.amount))),0);return <div><PageHead title="Class Fund" desc="Treasurer จัดการเงินกองกลางของห้อง">{canWrite&&<button className="primary" onClick={()=>setOpen(true)}><Plus size={16}/> เพิ่มรายการ</button>}</PageHead><div className="fundHero"><span>CURRENT BALANCE</span><b>฿ {balance.toLocaleString()}</b><small>ยอดคำนวณจากรายการที่บันทึกในระบบ</small></div><div className="panel tablePanel">{store.transactions.length?store.transactions.map(x=><div className="tableRow" key={x.id}><div><b>{x.title}</b><span>{x.note||'ไม่มีหมายเหตุ'} · {formatDate(x.date||x.created_at)}</span></div><strong className={x.type==='income'?'income':'expense'}>{x.type==='income'?'+':'−'} ฿{Number(x.amount).toLocaleString()}</strong>{canWrite&&<button className="dangerIcon" onClick={()=>update(s=>s.transactions=s.transactions.filter(y=>y.id!==x.id))}><Trash2 size={14}/></button>}</div>):<Empty icon={Wallet} title="ยังไม่มีรายการเงิน" desc="Treasurer สามารถเริ่มบันทึกรายรับรายจ่ายได้"/>}</div>{open&&<Modal title="เพิ่มรายการเงิน" onClose={()=>setOpen(false)}><div className="formGrid two"><Field label="ประเภท" value={f.type} onChange={v=>setF({...f,type:v})} options={['income','expense']}/><Field label="จำนวนเงิน" value={f.amount} onChange={v=>setF({...f,amount:v})} type="number"/><Field label="รายการ" value={f.title} onChange={v=>setF({...f,title:v})}/><Field label="วันที่" value={f.date} onChange={v=>setF({...f,date:v})} type="date"/></div><Field label="หมายเหตุ" value={f.note} onChange={v=>setF({...f,note:v})}/><button className="primary full" onClick={()=>{if(!f.title||!f.amount)return;update(s=>s.transactions.unshift({...f,id:uid(),created_by:user.id,created_at:isoNow()}));log('created','transaction');notify('บันทึกรายการเงินแล้ว');setOpen(false);setF({type:'income'})}}>บันทึก</button></Modal>}</div>}

function AttendancePage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canWrite=can(user,['owner','admin','teacher']);const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({title:''});return <div><PageHead title="Attendance" desc="เปิด session เช็กชื่อและเตรียมต่อ QR">{canWrite&&<button className="primary" onClick={()=>setOpen(true)}><QrCode size={16}/> เปิดเช็กชื่อ</button>}</PageHead><div className="attendanceGrid">{store.attendance.length?store.attendance.map(x=><div className="attendanceCard" key={x.id}><div className="qrBox"><QrCode size={34}/></div><div><span>ATTENDANCE SESSION</span><h3>{x.title}</h3><p>{formatDateTime(x.date)} · Token {String(x.token).slice(0,8)}</p></div><button className="secondary">เปิด QR</button></div>):<Empty icon={ScanLine} title="ยังไม่มี session" desc="Admin หรือ Teacher สามารถเปิดการเช็กชื่อได้"/>}</div>{open&&<Modal title="เปิดเช็กชื่อ" onClose={()=>setOpen(false)}><Field label="ชื่อ Session" value={f.title} onChange={v=>setF({...f,title:v})} placeholder="เช่น Biology Period 1"/><button className="primary full" onClick={()=>{if(!f.title)return;update(s=>s.attendance.unshift({...f,id:uid(),date:isoNow(),token:uid()}));log('created','attendance');notify('เปิดเช็กชื่อแล้ว');setOpen(false);setF({})}}>เปิด Session</button></Modal>}</div>}

function MembersPage({store,update,user,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;user:User;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){const canManage=can(user,['owner','admin']);const [open,setOpen]=useState(false);const [f,setF]=useState<Row>({roles:'student'});const [q,setQ]=useState('');const roles=Object.keys(roleLabel) as Role[];const filtered=store.members.filter(m=>`${m.name} ${m.email}`.toLowerCase().includes(q.toLowerCase()));return <div><PageHead title="Members & Roles" desc="สมาชิกหลาย Role ได้ และ Admin จัดการสิทธิ์จากที่เดียว"><div className="pageActions"><div className="inlineSearch"><Search size={15}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="ค้นหาสมาชิก…"/></div>{canManage&&<button className="primary" onClick={()=>setOpen(true)}><UserPlus size={16}/> เพิ่มสมาชิก</button>}</div></PageHead><div className="panel memberList">{filtered.length?filtered.map(m=><div className="memberRow" key={m.id}><div className="avatar large">{String(m.name||'?').slice(0,1)}</div><div className="memberIdentity"><b>{m.name}</b><span>{m.email||'ไม่มี email'}</span></div><div className="roleChips">{(Array.isArray(m.roles)?m.roles:[m.roles||'student']).map((r:Role)=><span key={r}>{roleLabel[r]||r}</span>)}</div>{canManage&&<button className="dangerIcon" onClick={()=>{update(s=>s.members=s.members.filter(x=>x.id!==m.id));notify('ลบสมาชิกแล้ว')}}><Trash2 size={15}/></button>} </div>):<Empty icon={Users} title="ยังไม่มีสมาชิก" desc="เพิ่มสมาชิกหรือให้เพื่อนเข้าด้วย Class Code"/>}</div>{open&&<Modal title="เพิ่มสมาชิก" onClose={()=>setOpen(false)}><div className="formGrid two"><Field label="ชื่อ" value={f.name} onChange={v=>setF({...f,name:v})}/><Field label="Email" value={f.email} onChange={v=>setF({...f,email:v})} type="email"/></div><label className="field"><span>ROLES</span><div className="rolePicker">{roles.map(r=><button type="button" className={(f.roles||'student').includes(r)?'active':''} key={r} onClick={()=>{const arr=String(f.roles||'student').split(',').filter(Boolean);const next=arr.includes(r)?arr.filter(x=>x!==r):[...arr,r];setF({...f,roles:next.join(',')})}}>{roleLabel[r]}</button>)}</div></label><button className="primary full" onClick={()=>{if(!f.name)return;const rr=String(f.roles||'student').split(',') as Role[];update(s=>s.members.push({...f,id:uid(),roles:rr,joined_at:isoNow()}));log('created','member');notify('เพิ่มสมาชิกแล้ว');setOpen(false);setF({roles:'student'})}}>บันทึก</button></Modal>}</div>}

function PulsePage({store}:{store:Store}){const metrics=[['Members',store.members.length,Users],['Subjects',store.subjects.length,GraduationCap],['Tasks',store.tasks.length,CheckSquare],['Exams',store.exams.length,FileText],['Files',store.files.length,FolderOpen],['Messages',store.messages.length,MessageCircle],['Events',store.events.length,PartyPopper],['Duty',store.duties.length,Brush]] as [string,number,LucideIcon][];return <div><PageHead title="Class Pulse" desc="ตัวเลขจากข้อมูลจริงของห้อง — ไม่มีข้อมูลปลอม"/><div className="pulseGrid">{metrics.map(([n,v,I])=><div className="pulseCard" key={n}><I size={18}/><span>{n}</span><b>{v}</b></div>)}</div><div className="panel pulseNote"><Activity size={19}/><div><b>Live classroom signal</b><p>Class Pulse จะละเอียดขึ้นเมื่อระบบถูกใช้งานจริง เช่น activity, attendance และ study presence</p></div></div></div>}
function LogsPage({store}:{store:Store}){return <div><PageHead title="Activity Logs" desc="ตรวจสอบการเปลี่ยนแปลงของระบบ"/><div className="panel logList">{store.activity.length?store.activity.map(x=><div className="logRow" key={x.id}><div className="logIcon"><Activity size={15}/></div><div><b>{x.action}</b><span>{x.entity} · {x.user||'system'}</span></div><small>{formatDateTime(x.created_at)}</small></div>):<Empty icon={Database} title="ยังไม่มี Activity" desc="กิจกรรมของผู้ใช้และ Admin จะถูกบันทึกตรงนี้"/>}</div></div>}
function FeaturesPage({store,update}:{store:Store;update:(fn:(s:Store)=>void)=>void}){const groups=[['Academic',['Schedule','Tasks','Exams','Calendar','Subjects']],['Class',['Class Files','Events','Duty','Weekly','Announcements','Gallery']],['Community',['Community','Study Rooms']],['Management',['Members','Attendance','Class Fund','Class Pulse']]] as [string,Page[]][];return <div><PageHead title="Feature Control" desc="เปิด/ปิดโมดูลที่ห้องต้องการใช้ เพื่อให้เมนูไม่รก"/><div className="featureGroups">{groups.map(([g,items])=><div className="panel" key={g}><div className="panelTitle"><span>{g}</span></div>{items.map(p=><div className="featureRow" key={p}><div><b>{th[p]}</b><span>{store.features[p]?'Enabled':'Disabled'}</span></div><button className={`toggle ${store.features[p]?'on':''}`} onClick={()=>update(s=>s.features[p]=!s.features[p])}><i/></button></div>)}</div>)}</div></div>}
function SettingsPage({store,update,log,notify}:{store:Store;update:(fn:(s:Store)=>void)=>void;log:(a:string,e:string,m?:any)=>void;notify:(x:string)=>void}){return <div><PageHead title="Settings" desc="การตั้งค่าประสบการณ์ของห้อง"/><div className="settingsGrid"><div className="panel"><div className="panelTitle"><span><Palette size={15}/> THEME</span></div><div className="themeChoices">{['sage','sand','sky','lavender','terracotta'].map(t=><button className={`themeChoice ${store.classroom.theme===t?'active':''} ${t}`} key={t} onClick={()=>{update(s=>s.classroom.theme=t);notify('เปลี่ยน Theme แล้ว')}}><i/>{t}</button>)}</div></div><div className="panel"><div className="panelTitle"><span>HUMOR MODE</span></div><div className="themeChoices">{['off','friendly','chaos'].map(t=><button className={`textChoice ${store.classroom.humor===t?'active':''}`} key={t} onClick={()=>update(s=>s.classroom.humor=t)}>{t}</button>)}</div><p className="settingsHelp">ใช้เพื่อกำหนดโทนข้อความของ Duty Wall เท่านั้น ไม่เปลี่ยนสิทธิ์หรือข้อมูลส่วนตัว</p></div><div className="panel dangerPanel"><div className="panelTitle"><span>LOCAL DATA</span></div><p>รีเซ็ตเฉพาะข้อมูล Local บนอุปกรณ์นี้ ไม่ลบ Supabase</p><button className="dangerOutline" onClick={()=>{if(confirm('ล้างข้อมูล Local ทั้งหมดบนอุปกรณ์นี้?')){localStorage.removeItem('classroom-os-v2');location.reload()}}}><RotateCcw size={15}/> Reset Local Data</button></div></div></div>}

createRoot(document.getElementById('root')!).render(<App/>);
